/* Seasons of Mystery – „Ein Tanz mit dem Tod“ (Buch S. 4–23), deutscher Text. Fertigkeiten in GROSSBUCHSTABEN werden als Probe-Marken dargestellt. */
window.VAE_MYS = window.VAE_MYS || {};
VAE_MYS.tod = {
 titel: "Ein Tanz mit dem Tod", buch: "vae_seasons", p: 4, zeit: "Frühling", ort: "Dalarna · Fudal am Siljan",
 warnung: "Gewalt, Tod, Gedankenkontrolle", bild: "som/tod_eroeffnung",
 tabs: [["Hintergrund","hg"],["Anreise","an"],["Orte","orte"],["Konfrontation","kf"],["|"],["Figuren","fg"],["Hinweise","hw"],["Handouts","ho"],["Nachspiel","ns","end"]],

 hg: {
  intro: "Dieses Mysterium für das Rollenspiel Vaesen führt die Spielercharaktere im Frühling in die malerische Provinz Dalarna, mit ihren grünen Wäldern, braunen Hütten und dem blauen Wasser des Siljan-Sees. Dort lernen sie die schwedische Tanz- und Volksmusiktradition kennen und sehen die Dunkelheit, die sich hinter der Freude der Musik verbirgt. Das Mysterium stellt ihren Scharfsinn und ihr soziales Geschick auf die Probe – und, wenn sie nicht vorsichtig sind, auch ihre Kampfkraft.",
  vorspiel: "Dieser erste Abschnitt beschreibt den Hintergrund des Mysteriums und die Konflikte, auf denen es beruht. Eine Einladung eröffnet die Sitzung, danach folgt die Reise nach Fudal, einer Sommeralm im Kirchspiel Mora. Am Ende steht ein Countdown von Ereignissen, den du als Spielleiter zu einem passenden Zeitpunkt im Mysterium in Gang setzt – und eine Katastrophe, die beschreibt, was geschieht, wenn die Spielercharaktere nicht handeln oder scheitern.",
  hinter: [
   "Fudal ist ein Fäbodvall – eine Sommeralm – im Dorf Nusnäs im Kirchspiel Mora. Es besteht aus verstreuten Hütten, wie ein kleines Dorf für sich, nahe der Fudalbucht im Siljan. Durch den Ort fließt ein Bach namens Fuån. Hier hüten die Almmägde die Kühe und Ziegen, die vor Kurzem zur Sommerweide nach Fudal gebracht wurden.",
   "Im Siljan lauert der Nöck (Grundregelwerk S. 144). Mit seiner Musik hat er Unglückliche zum Ertrinken in den See gelockt, in der Hoffnung, dass sie ihm in seinem Reich unter Wasser Gesellschaft leisten. Wenn er den Menschen beim Singen und Tanzen in den Dörfern zuhörte, beneidete er sie um ihre Gemeinschaft.",
   "In einer schlaflosen Nacht hörte die Almmagd Lisbets Boel ihn Fiedel spielen und war von der Musik so verzaubert, dass sie sich in den Nöck verliebte – und er in sie. Statt wie so viele vor ihr zu ertrinken, schwor sie, dem Nöck zu helfen, der ihr einen Platz an seiner Seite versprochen hat, wenn sie ihm Menschenopfer bringt. Nun planen die beiden, die Almmägde von Fudal zu ertränken. So hofft der Nöck endlich, eine Gefährtin zu haben, mit der er sein Reich teilen kann. Ein alter Wandteppich, der den Nöck zeigt, wurde später ebenfalls gestohlen.",
   "Doch der Nöck ist nicht der Einzige, der Lisbets Boel begehrt – der Fiedler Jons Gustav hat ebenfalls um ihr Herz geworben. Sie sprach aber stets liebevoll von einem anderen, unbekannten Musikanten, der der Mann ihrer Wahl sei. In seiner Verzweiflung nahm er Kontakt zum Nöck auf. Er stahl den schwarzen Kater der Almmagd Mattias Freja und brachte ihn an einen abgelegenen Uferabschnitt am Siljan, wo er ihn dem Nöck opferte, in der Hoffnung, dass dieser ihn seine Melodien lehre. Schließlich hörte der Nöck ihn und versprach es ihm – unter der Bedingung, dass Jons Gustav ihm Menschenopfer liefert.",
   "Jons Gustav kann Menschen mit den schwermütigen Weisen verzaubern, die er vom Nöck gelernt hat. So lockte er Pers Ida – eine der angestellten Almmägde – zum Wasser, um sie zu opfern, doch er brachte es nicht über sich. Am nächsten Morgen wachte sie am Seeufer ohne jede Erinnerung auf. Nun fürchtet Jons Gustav das Schicksal, das er über sich gebracht hat, und plant, die Fiedel des Nöcks zu stehlen. Mit ihr will er Lisbets Boel verzaubern und gemeinsam mit ihr dem Nöck und seinem Schicksal entkommen.",
   "Doch nun ist die Zeit gekommen, sein Versprechen einzulösen, und der Nöck erwartet, dass Jons Gustav Gesellschaft in sein Reich unter Wasser bringt. Er verlangt Menschenopfer und will, dass Jons Gustav auf seiner Fiedel spielt, um die Menschen von Fudal zum Wasser zu locken.",
   "Um Zeit zu gewinnen, führte Jons Gustav einige Kühe der Hofbesitzerin Swärds Jenny zum Wasser, um den Nöck wenigstens kurz zu besänftigen. Es genügte nicht. Nun erwartet der Nöck ein Menschenopfer, und seine Geduld schwindet.",
   "Der Nöck hat Boel erzählt, dass Gustav ebenfalls einen Handel mit ihm geschlossen hat, um ein großer Musikant zu werden. Nun planen Boel und der Nöck, Gustav und seine Liebe zu Boel auszunutzen. Jons Gustav hingegen ahnt nicht, dass der andere Fiedler, in den Boel angeblich verliebt ist, in Wahrheit der Nöck ist."
  ],
  mythic: "Wenn du dieses Mysterium statt im Mythischen Norden im Mythischen Britannien und Irland spielen möchtest, bietet sich die Westküste des Lough Corrib bei Oughterard in der Grafschaft Galway an. Gavelkind – ein System der Erbteilung, das Katholiken bis 1878 aufgezwungen wurde – zerstückelte die Höfe in immer kleinere Landstücke. Gab es keine männlichen Erben, gehörte der ganze Hof gemeinsam der Witwe und den Töchtern bis zur Heirat oder zum Tod. Ein solcher Hof könnte der Schauplatz dieses Mysteriums sein.",
  figs: [
   ["Der Nöck","Das Vaesen in den Tiefen des Siljan, das Menschen mit seiner Musik ins Wasser lockt. Ist in Lisbets Boel verliebt und hat Jons Gustav seine Musik gelehrt."],
   ["Swärds Jenny","Die Hofbesitzerin, der die ertrunkenen Tiere gehören, und Arbeitgeberin der Almmägde. Das Ertrinken ihrer Kühe setzt das Mysterium in Gang."],
   ["Lisbets Boel","Eine aufgeschlossene, beliebte Almmagd, die in den Nöck verliebt ist und von ihm verzaubert wird, damit sie ihm hilft, die anderen Almmägde zu ertränken."],
   ["Mattias Freja","Eine Almmagd, die für die anderen Mädchen den Ton angibt. Lisbets Boels engste Freundin."],
   ["Pers Ida","Eine junge, stille und zurückhaltende Almmagd. Sie war kürzlich in einen seltsamen Vorfall verwickelt: Sie wachte am Wasser auf, ohne zu wissen, wie sie dorthin gekommen war. Ist in Jons Gustav verliebt."],
   ["Jons Gustav","Ein einheimischer Fiedler, der vom Nöck spielen lernte und ihm nun Opfer liefern soll. Brachte Pers Ida zum Wasser, um sie zu opfern, konnte es aber nicht tun. Um Zeit zu gewinnen, ertränkte er Swärds Jennys Kühe."]
  ],
  konflikt: [
   "Der Hauptkonflikt dieses Mysteriums stellt den Nöck und Lisbets Boel gegen die Almmägde von Fudal. Der Nöck will seine Menschenopfer, und Lisbets Boel ist entschlossen, ihm seinen Wunsch zu erfüllen. Gemeinsam planen sie, Jons Gustav für ihren Plan einzusetzen.",
   "Der Nebenkonflikt besteht zwischen Jons Gustav und dem Nöck. Jons Gustav hat einen faustischen Handel mit dem Nöck geschlossen, um dessen Weisen zu lernen, bringt es aber nicht über sich, Menschen in den Tod zu locken. Zunehmend verzweifelt, besonders nach der Ankunft der Spielercharaktere, plant er, die Fiedel des Nöcks zu stehlen und seinem Pakt zu entkommen. Dann hofft er, Lisbets Boel mit ihrer wundersamen Musik zu verführen."
  ]
 },

 an: {
  hoName: "Handout 1A", karten: ["tod_karte_siljan"],
  einladung: ["Dieses Mysterium spielt im späten Frühling, kurz nachdem das Vieh zur Weide auf die Sommeralm getrieben wurde. Es beginnt damit, dass die Gesellschaft in ihrem Hauptquartier in Upsala einen Brief erhält. Der Brief ist auch als Handout 1A am Ende dieses Buches abgedruckt und steht auf der Webseite von Free League zum Download bereit. Er lautet:"],
  brief: {
   t1: "An wen es betrifft,",
   x: ["mein Name ist Jenny, und ich wende mich an Eure Gesellschaft, weil ich nicht weiß, was ich sonst tun soll. Ich bin nur die bescheidene Besitzerin des Swärdshofs in Nusnäs im Kirchspiel Mora.",
       "Es begann eines Morgens, als Pers Ida, eine Kulla, die auf der Sommeralm Fudal arbeitet, am Ufer des Siljan aufwachte, ohne zu wissen, wie sie dorthin gelangt war. Sie war wie gewöhnlich mit den anderen Kullor zu Bett gegangen. Die ganze Sache war sehr seltsam, und mehrere der Kullor sind seither beunruhigt.",
       "Ich schreibe Euch nun, nachdem zwei meiner Kühe im See ertrunken sind, trotz des Zauns, der sie hätte halten sollen. Jemand oder etwas hat sie dorthin geführt. Ich möchte glauben, dass keine der Kullor je etwas so Herzloses tun würde, doch ich fürchte, dass jemand etwas vor mir verbirgt.",
       "Die Polizei wollte nicht zuhören, also wende ich mich an Euch. Ich bin überzeugt, dass etwas Unnatürliches am Werk ist und dass es uns holen kommt.",
       "Da ich sonst niemanden habe, der mir hilft, hoffe ich von Herzen, dass dieser Brief Euch erreicht und dass Ihr es in Euren Herzen findet, mir Eure Hilfe und Euer Fachwissen anzubieten.",
       "Bitte antwortet umgehend, ich werde Euch in Mora treffen."],
   sig: "Ergebenst, Swärds Jenny"
  },
  vorb: ["Wie üblich können sich die Spielercharaktere in ihrem Hauptquartier auf die Reise vorbereiten und dadurch einen Vorteil erhalten (siehe Kapitel 9 im Grundregelwerk).",
         "Spielercharaktere, die in Upsala nach brauchbaren Informationen suchen, finden nur Grundlegendes: Nusnäs ist ein Dorf und Fudal ein Fäbodvall, beide im Kirchspiel Mora. Sie können jedoch einiges über die Traditionen und die Kultur Dalarnas lernen, etwa die Namensgebräuche und die Bedeutung der Musik. Es gibt auch Informationen über die Almwirtschaft und ihre Funktionsweise. Verwende dafür die Informationen aus dem Kasten Die Kultur Dalarnas.",
         "Wollen die Spielercharaktere nach Vaesen suchen, die mit Wasser oder Wasserläufen zu tun haben, erfordert das eine gelungene Probe auf GELEHRSAMKEIT. Es erscheinen der Bachross, die Meerjungfrau, der Kraken, das Irrlicht, der Nöck, die Seeschlange und die Fee."],
  kultur: {
   t: "Die Kultur Dalarnas",
   x: ["Zu dieser Zeit wird Dalarna überwiegend von Bauern bewohnt, die von der Flurbereinigung ausgenommen wurden. Ihre Höfe sind stattdessen nach einem System aufgeteilt, in dem jedes Kind einen gleichen Anteil an Land und Erbe erhält, wobei ein Mas oft zwei Anteile erbt. Ein Mann aus Dalarna heißt Mas und eine unverheiratete Frau oder ein Mädchen heißt Kulla; Menschen aus anderen Landesteilen setzen stets den Beinamen dal- davor, sodass daraus Dalmas und Dalkulla wird.",
          "Der Hof ist für Familien in Dalarna oft das Wichtigste. Die Namen der Leute bestehen normalerweise aus dem Hofnamen (meist der Vorname des Hofbesitzers), gefolgt vom eigenen Vornamen; die Brüder Tomas und Kosta vom Hof des Per hießen etwa Pers Tomas und Pers Kosta. Hofnamen können auch weiblich sein, wenn die Besitzerin eine Frau ist, oder von Soldatennamen abgeleitet wie Hane („Hahn“ wie das Bauteil der Feuerwaffe), Blixt („Blitz“), Wärre („schlimmer“) oder Spjut („Speer“).",
          "Die Landwirtschaft Dalarnas beruht weitgehend auf Transhumanz: Das Vieh wird in den Sommermonaten auf Wiesen und Weiden nahe Wäldern oder Bergen getrieben, während der bestellte Boden des Hofes dem Anbau von Getreide oder Winterfutter dient. Die Holzhütten auf den Weiden heißen Fäbodar, eine Gruppe von Fäbodar heißt Fäbodvall. Die Arbeit dort verrichten meist junge Almmägde, die tagsüber Kühe und Ziegen melken, Käse machen und Butter schlagen, die dann ins Dorf gebracht werden.",
          "Musik ist ein wesentlicher Teil der örtlichen Kultur. Hirtenmusik hört man oft zwischen den Fäbodar, entweder gesungen (das nennt man Kulning) oder auf Kuhhörnern gespielt. Sie ist sehr schön und verträumt und dient den Almmägden dazu, Kühe und Ziegen zu rufen.",
          "Die wichtigsten Musikanten sind aber die Fiedler, die bei Festen und anderen Zusammenkünften wie Taufen und Hochzeiten aufspielen. Dazu wird paarweise getanzt, etwa Polska oder Schottisch. Die Musik der Fiedler macht unglaublich tanzlustig, und von den Besten heißt es, sie hätten ihr Können durch Magie erworben. Bei diesen Festen trägt man oft Volkstracht."]
  },
  reise: ["Die Reise nach Mora ist eine dreitägige Kutschfahrt mit Übernachtungen in Gasthöfen in Avesta und Leksand, gefolgt von einer letzten Etappe nach Mora. Wie üblich können die Spielercharaktere während der Reise einen Vorteil erhalten (Grundregelwerk S. 24). Ihre Fahrt folgt dem Österdalälven tiefer nach Dalarna hinein, wo sich die Landschaft von weiten, offenen Feldern zu dichten Kiefern- und Fichtenwäldern wandelt.",
          "In Leksand erreichen die Charaktere die Mündung des Österdalälven in den Siljan und sehen das klare blaue Wasser vor sich ausgebreitet. Auf der anderen Seite liegt ihr Ziel Mora, wo sie nach einer Übernachtung in Leksand am späten Nachmittag ankommen.",
          "Als sie nach der langen Reise aus der Kutsche steigen, füllt sich ihre Lunge mit Luft, so klar wie das Wasser des Siljan. Am Horizont sehen sie Berge aufragen. Obwohl es Frühling ist und der Sommer naht, hält sich die winterliche Kälte noch in der Nacht.",
          "In Mora werden sie von Swärds Jenny begrüßt, die mit einem einfachen Pferdewagen wartet, um sie nach Fudal zu bringen. Hier können die Spielercharaktere alle Besorgungen erledigen, die sie haben.",
          "Sie merken, dass sie nach Norden gereist sind: Die Sonne geht früh am Morgen auf und spät am Abend unter, und der prächtige, farbenreiche Sonnenuntergang spiegelt sich im Wasser des Siljan. Erst um Mitternacht wird es völlig dunkel."],
  ankunft: ["Fudal liegt eine Stunde von Mora entfernt, und die Fahrt führt am glänzenden Wasser des Siljan entlang. Je näher sie kommen, desto dichter wird der Wald. Unterwegs erzählt Swärds Jenny, was geschehen ist, und die Spielercharaktere dürfen Fragen stellen. Sie sagt Folgendes:",
   "Nach einer Stunde erreichen die Spielercharaktere Fudal und sehen die Blockhütten und die Weiden mit grasenden Kühen, die von den Kullor gehütet werden. Ihre Ohren füllen sich mit dem zauberhaften Klang von Pers Idas melodischen Hirtenrufen.",
   "Mehrere der Almmägde versammeln sich um den Wagen und begrüßen die Spielercharaktere höflich. Swärds Jenny sagt, sie habe eine Hütte vorbereitet, in der die Spielercharaktere während ihrer Ermittlungen wohnen können. Die Kullor helfen, das Gepäck zur Holzhütte zu tragen. Sie ist einfach, hat aber Betten für alle, einen Holzofen und Gemeinschaftsbereiche, in denen sie arbeiten oder zusammensitzen können.",
   "Als der Abend naht, haben die Kullor ein Abendessen zubereitet, und den Spielercharakteren wird eine Mahlzeit aus Falunwurst, Knäckebrot, Kartoffeln, Rohmilch und frisch gemachtem Käse serviert. Die Mädchen, die das Essen auftragen, kichern und tuscheln miteinander. Sie erklären, dass Lisbets Boel Geburtstag hat und dass am Abend mit Musik und Tanz gefeiert wird. Die Feier findet nach dem Abendessen auf der Wiese statt."],
  jenny: ["Die Kulla, die auf mysteriöse Weise am Ufer des Siljan aufwachte, war Pers Ida. Sie hatte keine Erinnerung an das Geschehene, und an ihrem Körper waren flache Schnitte. Sie ist ein sehr braves Mädchen, wenn auch ein wenig still.",
          "Der Zaun um die Kuhweide war nicht beschädigt, also muss jemand die Kühe herausgelassen haben. Keine der Kullor hätte etwas so Grausames getan, wie die Kühe zu ertränken, zumal sie damit ihre eigene Lebensgrundlage ertränken würden.",
          "Es heißt seit jeher, dass man den Siljan und sein Wasser respektieren muss, und es sind schon Menschen darin ertrunken."]
 },

 cd: [
  {n:"Verzauberter Schlaf", x:"Lisbets Boel überzeugt Jons Gustav, dass die Spielercharaktere gefährlich sind und er sie abschrecken soll, indem er versucht, einen von ihnen zu töten. In der Nacht des Geburtstagsfestes lockt er einen von ihnen mit der verzaubernden Musik des Nöcks nach draußen. Er führt die Spielerfigur in den Wald, um sie zu töten, bringt es aber nicht über sich. Stattdessen lässt er sie dort liegen und rennt davon. Am Morgen wacht die Spielerfigur verwirrt auf, mit brennenden Schrammen und Kratzern am Körper, weil sie durch den Wald gelaufen ist, doch weder sie noch die anderen Spielercharaktere wissen, was geschehen ist. Die betroffene Spielerfigur muss eine Furchtprobe gegen Furcht 1 ablegen. Sie bemerkt nichts, fühlt sich aber wie in tiefem Schlaf. Andere Spielercharaktere, die wach sind und es sehen, stellen fest, dass sie die verzauberte Figur nicht erreichen können, während sie gleichzeitig traurige, aber schöne Fiedelmusik aus etwas Entfernung hören. Die verzauberte Figur tut alles, um der Melodie zu folgen, und greift notfalls zur Gewalt. Machen die Spielercharaktere Lärm, hört Jons Gustav auf zu spielen, und die verzauberte Figur kommt wieder zu sich, als wäre nichts gewesen. Jede anwesende Spielerfigur muss eine Furchtprobe gegen Furcht 1 ablegen."},
  {n:"Pers Ida", x:"Pers Ida sieht, wie Lisbets Boel sich am See mit einem geheimnisvollen Mann trifft, und beobachtet dann, wie der Nöck seine wahre Gestalt annimmt. Ida versucht zu fliehen, wird aber entdeckt. Der Nöck spielt seine Musik und lockt sie ins Wasser hinunter, wo sie ertrinkt. Am Morgen wird sie von einer verzweifelten Mattias Freja oder von den Spielercharakteren am Ufer gefunden."},
  {n:"Fiedel am See", x:"Lisbets Boel bittet Jons Gustav, sie an der Fudalbucht zu treffen, doch dort erscheint der Nöck, und Jons Gustav begreift, dass er in eine Falle gelaufen ist. Der Nöck verzaubert Jons Gustav, sodass er nicht mehr aufhören kann zu fiedeln – er muss spielen, bis seine Finger bluten, und jedem Befehl des Nöcks gehorchen. Dann spielt Jons Gustav die Musik des Nöcks, und alle, die sie hören, werden verzaubert, zum Wasser gebracht und ertränkt. Ist Jons Gustav etwas zugestoßen, spielt der Nöck selbst die Fiedel. Mehr dazu unter Konfrontation."},
  {n:"Katastrophe", kat:1, x:"Greifen die Spielercharaktere nicht ein, bringt Jons Gustav Opfer ans Ufer des Siljan und ertränkt sie. Er ist nun dazu verdammt zu spielen, bis seine Knöchel ganz abgewetzt sind. Ist Jons Gustav etwas zugestoßen, holt der Nöck seine Opfer selbst. Lisbets Boel nimmt schließlich ihren Platz an der Seite des Nöcks ein, doch leider ertrinkt auch sie. Man sagt, nachts sei vom Siljan eine klagende Melodie zu hören, wie von jemandem, der Gesellschaft sucht, und wer Fudal besucht, wird dort nur den Tod finden."}
 ],
 pp: {cd:9}, figOrder: ["jenny","boel","ida","gustav","freja","maegde"],
 cdIntro: "Das Eingreifen der Spielercharaktere löst Reaktionen bei Lisbets Boel und Jons Gustav aus, die in ihrem Handeln immer verzweifelter werden, je ungeduldiger der Nöck wird. Wenn die Spielercharaktere die Geschichte nicht in eine andere Richtung lenken, endet sie schließlich in einem Unglück. Nutze die folgenden Ereignisse, um das Spiel bei Bedarf zu beschleunigen und die Spieler auf die Konfrontation zuzutreiben.",

 orteIntro: "Die folgenden Absätze fassen die wichtigsten Orte zusammen, die die Spielercharaktere in diesem Mysterium besuchen können: die Wiese, das Hüttendorf, der Wald und die Fudalbucht. Wollen die Spielercharaktere andere Orte untersuchen, kannst du improvisieren; es ist aber auch völlig in Ordnung zu erklären, dass der betreffende Ort nicht zum Mysterium gehört und es dort nichts Interessantes gibt.",
 orte: [
  {id:"wiese", t:"Die Wiese", p:10, karte:"tod_karte_fudal", hier:["gustav","jenny","freja","ida","boel"],
   text:["Auf der Wiese rund um die Hütten grasen tagsüber die Kühe, bevor sie für die Nacht auf die eingezäunte Weide gebracht werden. Am Abend der Ankunft der Spielercharaktere findet eine Feier zu Lisbets Boels Geburtstag statt. Alle auf der Fäbodvall nehmen teil, und Jons Gustav spielt dazu auf.",
          "Die Mädchen haben sich in Volkstracht gekleidet und den Fiedler Jons Gustav eingeladen, auf dem Fest zu spielen. Als die Musik beginnt, kommt die Feier bald in Schwung, und alle Mädchen tanzen, besonders als der Aquavit herumgereicht wird. Es ist praktisch unmöglich, sich von der Musik nicht mitreißen zu lassen, die fast magisch ist. Die Weisen der Fiedel mischen sich mit Lachen und fröhlichem Rufen. Einen Moment lang lässt das Fest alle die seltsamen und rätselhaften Vorfälle vergessen.",
          "Nachts sind die Tiere auf einer Weide mit Rundholzzaun untergebracht, tagsüber grasen sie hier. Es sind mehrere Kühe sowie Ziegen, die den Bauern von Nusnäs gehören."],
   herausf:["Die Spielercharaktere können mittanzen. Lisbets Boel fordert dann einen von ihnen zum Tanz auf. Die Tanzenden können BEWEGLICHKEIT einsetzen, um mitzuhalten. Bei Erfolg sind die Leute von den Bewegungen der Spielerfigur beeindruckt, was später in einem Gespräch mit einem der Mädchen wie eine gelungene Probe auf BEOBACHTUNG oder MANIPULATION wirkt. Wird die Probe gepusht, bedeutet ein Misserfolg, dass sie stolpern und fallen, während alle über sie lachen.",
            "Jons Gustav ist über die Anwesenheit der Spielercharaktere besorgt und fürchtet, dass sie seine Pläne durchkreuzen. Nach ein paar Gläsern fordert er womöglich einen von ihnen zum Armdrücken heraus. Ihn zu besiegen erfordert eine gelungene Probe auf KRAFT gegen seine KRAFT. Gewinnt die Spielerfigur, verlässt Jons Gustav wütend die Wiese und hält sie für eine noch größere Bedrohung, weshalb er von nun an vorsichtiger im Umgang mit ihr ist. Bei einem Misserfolg erleidet die Spielerfigur einen körperlichen Zustand, und Jons Gustav hält sich ihr für überlegen.",
            "Pers Ida ist da, sagt aber wenig und will vor all den Leuten nicht darüber sprechen, was geschehen ist. Mit einer gelungenen Probe auf MANIPULATION können die Spielercharaktere sie zum Reden bringen; dann nimmt sie sie beiseite und erzählt es ihnen. Misslingt die Probe, bittet sie sie, morgen zu ihr zu kommen.",
            "Spielercharaktere, die sich nachts der Weide zu sehr nähern oder sie betreten, riskieren, die Tiere zu erschrecken, und werden womöglich von Ziegen oder Kühen gestoßen und gejagt. Die Spielercharaktere müssen eine Probe auf HEIMLICHKEIT bestehen, um kein Tier aufzuscheuchen. Misslingt sie oder schleichen sie gar nicht erst, müssen sie eine Probe auf BEWEGLICHKEIT bestehen, um nicht von einem Tier gestoßen zu werden. Bei einem Misserfolg erleiden sie einen körperlichen Zustand. Nach dem Vorfall erscheint eines der Mädchen und singt ihr Hirtenlied, um die Tiere zu beruhigen."],
   hinwText:"Trotz der festlichen Stimmung können die Spielercharaktere eine Menge Informationen gewinnen, vieles davon Klatsch, einfach indem sie die hier arbeitenden Mädchen fragen. Sie können als Gruppe antworten; soll eine bestimmte Person ihre Fragen beantworten, kann das Mattias Freja sein.",
   hinw:[
    {id:"w1", x:"Swärds Jenny möchte, dass sich die Spielercharaktere willkommen fühlen, und stellt sie verschiedenen Nichtspielercharakteren vor. Sie sagt, die meisten Leute würden sich hüten, ihnen zu vertrauen, egal wie höflich sie seien."},
    {id:"w2", x:"Bringen die Spielercharaktere Pers Ida zum Reden, erklärt sie, dass sie kürzlich ganz allein unten an der Bucht aufgewacht ist, nur im Nachthemd. Sie sagt ihnen, wo sie die Stelle finden. Sie war nicht verletzt, hatte aber leichte Kratzer an den Füßen vom Barfußlaufen. Sie erinnert sich an nichts Seltsames in der Nacht ihres Verschwindens – sie ging wie immer zu Bett und trinkt nicht, also kann sie nicht betrunken gewesen sein. Sie wohnt allein in einer der Hütten, daher hat leider niemand etwas gesehen oder gehört. Zum Schluss sagt sie, sie habe nach dem Vorfall ein sehr unangenehmes Gefühl im Körper gehabt, als wäre ihr etwas Unnatürliches widerfahren. Sie erwähnt auch ein Tagebuch, hat aber sonst nichts gesehen, was den Spielercharakteren helfen könnte."},
    {id:"w3", x:"Fragen die Spielercharaktere nach den ertrunkenen Kühen, sagen alle Mädchen, es sei sehr traurig gewesen. Sie sorgen gut für die Tiere und hätten so etwas bestimmt nicht zugelassen. Auf die Frage, wer die Kühe zuletzt gesehen hat, erklären die Mädchen, dass Lisbets Boel in jener Nacht abgeschlossen hat. Die Spielercharaktere werden aber wohl während der Feier keine Gelegenheit haben, mit ihr zu sprechen, da sie zu sehr gefeiert wird. Bekommen sie doch einen Moment mit ihr, sagt Lisbets Boel, sie spreche gern morgen mit ihnen, wolle aber jetzt das Fest genießen und schlage vor, dass die Spielercharaktere das auch tun."},
    {id:"w4", x:"Mehrere Mädchen sind von dem Fiedler Jons Gustav beeindruckt. Sein Spiel war früher ziemlich einfach und gefühllos, jetzt scheint er ein richtiger Virtuose geworden zu sein. Sie fragen sich, ob er Unterricht genommen hat, und wenn ja, bei wem. Sie fügen hinzu, er hätte dabei auch ein paar Höflichkeitsstunden nehmen sollen."},
    {id:"w5", x:"Auf die Frage nach anderen Fiedlern oder wer Jons Gustav unterrichtet haben könnte, erzählen die Mädchen, dass sie spätnachts Musik vom See hören. Die Melodien sind erhaben, doch niemand weiß, wer sie spielt. Lisbets Boel ist nachts oft wach und weiß vielleicht mehr."},
    {id:"w6", q:"Handout 1C", x:"Heute Abend wird Jons Gustav Lisbets Boel heimlich einen Liebesbrief zustecken, der ihr seine Pläne beschreibt. Mit einer gelungenen Probe auf WACHSAMKEIT können die Spielercharaktere bemerken, wie er ihn übergibt. Lisbets Boel weigert sich, ihn zu zeigen, doch die Spielerfigur kann versuchen, ihn mit einer gelungenen Probe auf HEIMLICHKEIT gegen ihre BEOBACHTUNG zu stehlen."},
    {id:"w7", x:"Spielercharaktere, die die Weide untersuchen, sehen, dass ihr Zaun nicht beschädigt ist und das Tor kein Schloss hat, sodass jeder Swärds Jennys zwei Kühe hinauslassen konnte. Eine gelungene Probe auf NACHFORSCHUNG enthüllt Fußspuren, die in den Wald führen."}
   ],
   paranoia: {t:"Paranoia", x:["Ein Teil des Mysteriums besteht darin, Paranoia zu erzeugen und die Spielercharaktere im Unklaren darüber zu lassen, wem sie trauen können. Das Mysterium enthält Hinweise darauf, dass jemand mit dem Nöck gemeinsame Sache macht, und einige, die auf Lisbets Boel deuten. Unten stehen Vorschläge für Ereignisse, die in verschiedenen Abschnitten des Abenteuers eintreten können.",
    "Jemand spioniert die Spielercharaktere vor ihrem Fenster aus. Mit einer gelungenen Probe auf WACHSAMKEIT bemerken sie es, doch die Person rennt weg, bevor sie sehen können, wer es ist.",
    "Die Spielercharaktere finden auf einem ihrer Betten einen Zettel mit der Aufforderung, zu verschwinden. Der Zettel ist als Handout 1B abgedruckt. Er stammt von Lisbets Boel.",
    "Die Spielercharaktere werden an der Fudalbucht beobachtet; jemand spioniert sie aus dem Wald aus. Merken sie es, rennt die Person weg, bevor sie sie sehen können. Fangen sie die spionierende Person, ist es Lisbets Boel.",
    "Fragen die Spielercharaktere eines der Mädchen (Pers Ida, Mattias Freja oder eine namenlose Figur), ob es rätselhafte Vorfälle gegeben habe, zögern sie zu reden. Eine gelungene Probe auf BEOBACHTUNG bringt sie dazu zuzugeben, dass seltsame Dinge geschehen sind, doch aus Angst, jemand könnte zuhören, sagen sie nichts weiter.",
    "Lisbets Boel lässt den Nöck entweder Mattias Freja oder Swärds Jenny verzaubern; diese kommt nachts zu den Spielercharakteren, um seine Botschaft zu überbringen. Die verzauberte Person spricht mit monotoner Stimme und sagt, die Spielercharaktere müssten gehen, sonst werde Blut vergossen – Blut, das an ihren Händen kleben werde. Mit einer gelungenen Probe auf BEOBACHTUNG oder HEILKUNDE erkennen die Spielercharaktere, dass die Person hypnotisiert ist und für jemand anderen spricht. Danach müssen sie eine Furchtprobe gegen Furcht 1 ablegen.",
    "Die Spielercharaktere werden von Verzauberungen und Flüchen rund um Wasser oder Musik verfolgt. Sie finden Kaulquappen in ihrem Trinkwasser oder blühende Seerosen im Bierfass, oder sie ersticken fast an einem Rubinring, der irgendwie im Bauch eines Fisches gelandet ist. Auch die Musik folgt ihnen – vielleicht erinnert das Knarren eines Wagenrads an die wehmütigen Weisen der Fiedel, oder Leute beim Spaziergang beginnen Tanzschritte zu machen. Dafür kann eine Furchtprobe gegen Furcht 1 nötig sein.",
    "In der Nacht vor Schritt 2 des Countdowns tritt Pers Ida an die Spielercharaktere heran und bittet sie, morgen zu ihrer Hütte zu kommen. Sie glaubt, etwas gesehen zu haben, das ihnen helfen könnte, will aber nichts sagen, bevor sie sicher ist. Sie kann diese Botschaft auch als Zettel überbringen."]},
   zettel:{t:"Der Zettel auf dem Bett", x:"Neugierige Leute wie ihr täten gut daran, zu gehen. Lasst uns das selbst regeln."}
  },
  {id:"huetten", t:"Das Hüttendorf", p:16, karte:"tod_karte_fudal", hier:["boel","freja","ida","jenny","maegde","nicklas"],
   text:["Der größte Teil von Fudal besteht aus dem Hüttendorf mit mehreren Blockhütten unterschiedlicher Größe. Einige sind größer und bieten Platz für ganze Familien (eine davon bewohnen die Spielercharaktere), während viele der Almmägde in kleineren, einfacheren Hütten für ein bis vier Personen wohnen. Die großen Hütten haben eigene Küchen und Aborte, die kleinen teilen sich eine größere Küche und einen Abort.",
          "Swärds Jenny wohnt allein in einer der größeren Hütten, da ihre Familie derzeit auf dem Hof zu Hause ist, und sie bietet den Spielercharakteren gern eine Tasse Kaffee an, wenn sie reden möchten. Lisbets Boel und Mattias Freja teilen sich eine kleinere Hütte. Wenn die Spielercharaktere sie besuchen, bürstet Lisbets Boel sich das Haar, und Mattias Freja häkelt neben ihr, beide plaudern fröhlich über die jüngsten Feierlichkeiten. Pers Ida wohnt allein in einer der kleineren Hütten und ruht sich aus, als die Spielercharaktere sie aufsuchen."],
   herausf:["Haben die Spielercharaktere das Vertrauen der Almmägde noch nicht gewonnen, müssen sie Proben auf MANIPULATION bestehen, um sie zu befragen, besonders Lisbets Boel und Mattias Freja.",
            "Betrachten die Spielercharaktere eines der Mädchen als Verdächtige und wollen unbemerkt in deren Hütten gelangen, erfordert das gelungene Proben auf HEIMLICHKEIT.",
            "Sobald Schritt 2 des Countdowns eingetreten ist, besucht der Nöck (in Menschengestalt) die Fäbodvall und spielt traurige, düstere Musik zu Ehren der verstorbenen Pers Ida. Glaubt er, dass die Spielercharaktere ihn verdächtigen, lässt er Tische und Hocker geheimnisvoll tanzen und entkommt im folgenden Tumult. Die Möbel hören auf, sich zu bewegen, wenn er fort ist. Wer das miterlebt, muss eine Furchtprobe gegen Furcht 1 ablegen."],
   hinwText:"Die Spielercharaktere können im Hüttendorf viele Informationen gewinnen, hauptsächlich von den Almmägden. Wenn sie nicht weiterkommen und keinen der Nichtspielercharaktere erreichen, mit denen sie sprechen wollen, kann Swärds Jenny ihnen helfen und sie zu jeder gewünschten Person begleiten, wo sie die nötigen Informationen bekommen. Haben die Spielercharaktere auf der Wiese mit keiner Almmagd gesprochen, können sie sie in ihren Hütten sprechen und die dort unter Hinweise (S. 12) aufgeführten Informationen erfahren. Hier sind die Hinweise im Hüttendorf:",
   hinw:[
    {id:"h1", x:"Fragen die Spielercharaktere Lisbets Boel nach der Nacht, in der die Kühe ertranken, antwortet sie, sie habe sie auf die Weide getrieben und sich vergewissert, dass das Tor geschlossen und verriegelt war. Sie habe beim Gehen niemanden gesehen und sei in die Hütte zurückgegangen, wo sie und Mattias Freja bis zum Morgen tief geschlafen hätten. Keine von ihnen würde je den Tieren etwas antun, wie auch Mattias Freja bestätigt."},
    {id:"h2", x:"Lisbets Boel schläft nachts oft schlecht, und das weiß in Fudal jeder. Fragen die Spielercharaktere, ob sie nachts etwas Seltsames gesehen oder gehört habe, spricht sie nur von den Geräuschen des Waldes und des Sees und erwähnt nie die Musik. Als die Kühe verschwanden, schlief sie allerdings, was Mattias Freja bestätigen kann. Mit einer gelungenen Probe auf BEOBACHTUNG gegen ihre MANIPULATION können sie ihre Lüge durchschauen. Dann gibt sie zu, nachts Musik vom Siljan gehört zu haben, weiß aber nicht, wer oder was dafür verantwortlich ist."},
    {id:"h3", x:"Fragen die Spielercharaktere eine Almmagd, ob andere Tiere verschwunden sind, berichtet sie traurig, dass Mattias Frejas schwarzer Kater Nisse vor etwa einem Monat verschwunden ist."},
    {id:"h4", x:"Mattias Freja kann auch erzählen, dass sie glaubt, Jons Gustav sei in Lisbets Boel verliebt, doch als sie Boel darauf ansprach, schien diese völlig uninteressiert. Vielleicht gehört ihr Herz jemand anderem? Sie vermutet außerdem, dass Pers Ida in ihn verliebt ist."},
    {id:"h5", q:"Handout 1C", x:"Die Spielercharaktere können nach dem Liebesbrief suchen, den Jons Gustav Lisbets Boel zugesteckt hat. Sie hält ihn unter ihrer Matratze versteckt, und sie müssen eine herausfordernde Probe auf NACHFORSCHUNG bestehen, um ihn zu finden. Haben sie ihr Vertrauen gewonnen, kann Mattias Freja ihnen beim Suchen helfen, was die Schwierigkeit auf Normal senkt. Lisbets Boel hat hier vielleicht auch den alten Wandteppich versteckt."},
    {id:"h6", x:"Haben die Spielercharaktere den Liebesbrief gelesen und fragen Lisbets Boel, wer der andere Mann ist, sagt sie, es spiele keine Rolle, da es nur eine einmalige Sache gewesen sei. Eine gelungene Probe auf MANIPULATION kann sie dazu bringen zuzugeben, dass er Nicklas heißt – der andere Fiedler, der ab und zu nach Fudal kommt."},
    {id:"h7", x:"Auf die Frage nach den Fußspuren sagt Swärds Jenny, dass alle den Wald meiden, besonders nachts, und dass sich niemand allein unter seine schattigen Zweige wagt."},
    {id:"h8", q:"Handout 1D", x:"Nach Schritt 2 des Countdowns können die Spielercharaktere finden, was Pers Ida in ihr Tagebuch geschrieben hat; es liegt auf ihrem Nachttisch. Der Eintrag entstand in der Nacht vor ihrem Tod und ist als Handout 1D abgedruckt. Der alte Wandteppich könnte hier ebenfalls liegen, wo Pers Ida ihn vor ihrem Tod gefunden hat. Mattias Freja kann erzählen, dass Pers Ida in der Nacht ihres Todes etwas gesehen zu haben schien, falls die Spielercharaktere zu ihrer Hütte gelenkt werden müssen."},
    {id:"h9", x:"Fragen die Spielercharaktere, wo Jons Gustav wohnt, sagen die Almmägde, er habe eine kleine Hütte im Wald, in der er die Nächte verbringt."},
    {id:"h10", x:"Besucht der Nöck das Hüttendorf in Menschengestalt, können die Spielercharaktere seine unheilige Gestalt enthüllen, indem sie ihm den Hut vom Kopf reißen und das dritte Auge auf seiner Stirn zeigen. Sie können auch eine herausfordernde Probe auf BEOBACHTUNG versuchen; bei Erfolg versucht der Nöck zu fliehen."},
    {id:"h11", x:"In der großen Speisehütte hing früher ein alter Wandteppich mit dem Nöck, der vor einer Weile verschwand. Eine der Almmägde kann sein Motiv grob beschreiben: eine seltsame Gestalt, die von einem Priester gebannt wird. Siehe den Kasten Der Wandteppich."}
   ],
   kasten:[
    {t:"Der Nöck in Menschengestalt", x:"Der Nöck kann menschliche Gestalt annehmen, um sich unter die Leute von Fudal zu mischen. Er nennt sich Nicklas und sieht aus wie ein großer Mann Ende zwanzig mit langem schwarzem Haar und Bart. Er trägt einen Hut, der ein drittes Auge auf seiner Stirn verbirgt, und tut alles, um es verborgen zu halten. Er ist ziemlich schweigsam, hat aber einen gewissen geheimnisvollen Charme. Er stellt sich als Landstreicher ohne Familie vor, weshalb er keinen Nachnamen hat.", p:13},
    {t:"Der Wandteppich", x:"Ein alter Wandteppich, höchstens 40 × 30 cm groß, hing früher in der Speisehütte. Er wurde im späten 17. Jahrhundert angefertigt und ist schlicht gearbeitet. Er zeigt eine grauenerregende menschenähnliche Gestalt, die zu einem See flieht, verfolgt von einem Priester mit einem Kruzifix in der Hand. Das Wesen hat drei Augen, und auf seiner Schulter sitzt eine schwarze Katze. Das Motiv zeigt, wie der Nöck von einem Priester gebannt wird.<br><br>Der Wandteppich wurde vor einer Weile gestohlen, entweder von Lisbets Boel oder von Jons Gustav, je nachdem, wo die Spielercharaktere ihn finden, damit niemand herausfindet, wie man den Nöck bannt. Das Mysterium nennt viele Vorschläge, wo er versteckt sein könnte, doch die Diebe können ihn auch am Körper tragen. Werden sie mit dem Wandteppich erwischt, behaupten sie, ihn gefunden zu haben und gerade im Begriff gewesen zu sein, ihn zurückzubringen. Lisbets Boel ist eine ausgezeichnete Lügnerin, und die Charaktere müssen eine herausfordernde Probe auf BEOBACHTUNG bestehen, um ihre Täuschung zu durchschauen.<br><br>Das Motiv des Wandteppichs ist nicht einzigartig – es gibt viele ähnliche Wandteppiche, die dunkle Mächte zeigen, die durch christliche Symbole gebannt werden, oder die vor den Gefahren der Versuchung warnen. Folglich kann keine der Almmägde den Wandteppich genau beschreiben, sondern nur als „noch ein Teufel, der gebannt wird“. Die meisten können sogar scherzhaft darüber reden.<br><br>Eine Spielerfigur, die den Wandteppich findet und untersucht, kann eine Probe auf GELEHRSAMKEIT ablegen, um zu erkennen, dass die Gestalt den Nöck darstellt, der von christlichen Symbolen in die Tiefe zurückgetrieben wird.", p:18}
   ]
  },
  {id:"wald", t:"Der Wald", p:18, karte:"tod_karte_fudal", hier:["gustav"],
   text:["Der Wald rund um das Hüttendorf besteht hauptsächlich aus hohen Kiefern und Fichten. Er ist dicht und verworren, und man sollte beim Gehen vorsichtig sein, denn in der Gegend gibt es Bären. Alle Almmägde meiden den Wald bei Nacht. Im Spätsommer und Herbst gehen sie meist dorthin, um Beeren oder Pilze zu sammeln.",
          "Tief im Dickicht des Waldes steht eine kleine Holzhütte, in der Jons Gustav bei seinen Besuchen die Nächte verbringt. Sie ist sehr bescheiden, mit einem Bett und einem Nachttisch, einer einfachen Küche und einem Esstisch."],
   herausf:["Folgen die Spielercharaktere den Fußspuren, die sie an der Weide gefunden haben, erfordert es eine gelungene Probe auf WACHSAMKEIT, sie durch das Dickicht zu verfolgen. Gelingt sie, führen die Spuren zu Jons Gustavs Hütte. Misslingt sie, verirren sie sich und laufen Gefahr, einem Bären zu begegnen. Die Werte des Bären stehen auf S. 168 im Grundregelwerk.",
            "Spielercharaktere, die den Wald erkunden, sehen am See eine Gestalt, die tiefer in den Wald geht. Das ist Jons Gustav. Mit gelungenen Proben auf HEIMLICHKEIT können sie ihm unbemerkt folgen. Misslingt eine, beginnt Jons Gustav zu rennen, und die Spielercharaktere müssen eine gelungene Probe auf BEWEGLICHKEIT bestehen, um ihn einzuholen. Misslingt auch die, entkommt Jons Gustav; gelingt sie, holen sie ihn ein, wenn er seine Hütte erreicht, ohne dass er es bemerkt. Nach einer Weile verlässt er die Hütte, sodass die Charaktere unbemerkt hineingelangen können.",
            "Jons Gustav hat nahe seiner Hütte eine Stahlfalle aufgestellt, um sie vor Bären zu schützen, und die Spielercharaktere müssen eine Probe auf WACHSAMKEIT bestehen, um nicht hineinzutreten. Eine Figur, bei der sie misslingt (zufällig bestimmt), erleidet einen körperlichen Zustand sowie die körperliche kritische Verletzung Fußverletzung (Grundregelwerk S. 65).",
            "Jons Gustavs Hütte ist verschlossen. Die Spielercharaktere müssen eine Probe auf HEIMLICHKEIT bestehen, um das Türschloss zu knacken, eine Probe auf NACHFORSCHUNG, um den in einer Wandritze versteckten Schlüssel zu finden, oder eine Probe auf KRAFT, um die Tür aufzubrechen.",
            "Fühlt sich Jons Gustav von den Spielercharakteren bedroht, greift er womöglich an, besonders wenn er sie überfallen kann. Er warnt sie dann und bittet sie zu gehen, beteuert aber, er wolle ihnen nichts Böses. Er greift an, indem er auf seiner Fiedel spielt, und rennt davon, wenn die Lage brenzlig wird.",
            "Die Spielerfigur, die nach Schritt 1 des Countdowns im Wald aufwacht, hat vielleicht das Pech, einem Bären zu begegnen. Sie kann versuchen, sich mit einer Probe auf HEIMLICHKEIT vor dem Bären zu verstecken oder mit BEWEGLICHKEIT zu fliehen. Bei einem Misserfolg kann der Bär angreifen."],
   hinwText:"Die Spielercharaktere können im Wald viele Informationen gewinnen, vor allem in Jons Gustavs Hütte:",
   hinw:[
    {id:"f1", q:"Handout 1E", x:"Die Hütte ist klein und spartanisch, daher leicht zu durchsuchen. Ein Blick auf den Nachttisch oder eine gelungene Probe auf NACHFORSCHUNG fördert einen unfertigen, zerknüllten Brief von Jons Gustav zutage (siehe Handout 1E). Er verrät, dass ein Messer, mit dem man Fiedelsaiten durchtrennt hat, den Nöck am Zaubern hindern kann."},
    {id:"f2", q:"Handout 1C", x:"Haben die Spielercharaktere nicht gesehen, wie Jons Gustav Lisbets Boel den Brief gab, liegt er hier in der Hütte, gefaltet auf dem Küchentisch, bereit, ihr übergeben zu werden. Den Brief siehe Handout 1C."},
    {id:"f3", x:"Spielercharaktere, die Jons Gustav überwältigen oder Kontakt zu ihm aufnehmen, können versuchen, ihn zu befragen und zu sehen, wem seine Loyalität gilt (etwa wenn sie vermuten, dass er die Spielerfigur in den Wald gelockt hat). Zunächst leugnet er, doch mit Beweisen konfrontiert nimmt er alle Schuld auf sich und sagt, er habe es nur getan, um die Macht seiner Musik zu beweisen. Eine gelungene Probe auf BEOBACHTUNG durchschaut aber seine Lügen; dann gibt er zu, dass er versucht hat, jemanden von ihnen zu verletzen, es aber nicht über sich brachte. Jons Gustav will keinen Verdacht auf Lisbets Boel lenken, und wenn er verzweifelt ist, versucht er vielleicht, sie zu überzeugen, dass Mattias Freja verantwortlich ist, oder alles auf den Nöck zu schieben, falls die Spielercharaktere erkannt haben, dass dieser das Vaesen ist, mit dem sie es zu tun haben."},
    {id:"f4", x:"Geraten die Spielercharaktere mit Jons Gustav in einen Kampf und können ihn überwältigen, oder wenn er entkommt, lässt er sein Messer fallen. Es wurde zum Durchtrennen von Fiedelsaiten benutzt und ist daher gegen den Nöck nützlich."},
    {id:"f5", x:"Auf die Frage nach dem anderen Fiedler sagt Jons Gustav, er kenne dessen Namen nicht, liefert aber eine Beschreibung, die auf Nicklas passt."},
    {id:"f6", x:"Der alte Wandteppich kann hier gefunden werden. Er könnte unter einer Bodendiele in Jons Gustavs Hütte versteckt oder in einem Baumhain vergraben sein. In beiden Fällen erfordert das Finden eine gelungene Probe auf NACHFORSCHUNG. Mehr dazu im Kasten auf S. 18."}
   ]
  },
  {id:"bucht", t:"Die Fudalbucht", p:20, karte:"tod_karte_fudal", hier:["boel","freja"],
   text:["Die Fudalbucht ist eine Bucht im Siljan mit seinem herrlich blauen Wasser. Sie ist ein felsiger Strand, der flach beginnt, aber schnell tief wird, denn der Siljan ist 120 Meter tief. Der Nöck hat seine Behausung etwas weiter draußen, tief unten auf dem Grund des Sees, kommt aber näher ans Ufer, um Menschen ins Wasser zu locken.",
          "Die glatte Oberfläche des Sees ist mit Seerosen übersät, und nachts wimmelt es hier von Stechmücken. Obwohl es Frühling ist, ist das Wasser noch ziemlich kalt."],
   herausf:["Spielercharaktere, die nachts im Wasser laufen, laufen Gefahr, auf einem glitschigen Stein auszurutschen, wenn sie nicht WACHSAMKEIT einsetzen. Ein solcher Unfall führt zu einem körperlichen Zustand.",
            "Der Nöck könnte den Spielercharakteren auflauern. Sein Hauptziel ist nicht, sie zu ertränken, und wenn er befürchtet, entdeckt oder entlarvt zu werden, hat er menschliche Gestalt angenommen. Er kann aber seine Magie einsetzen und Musik spielen, um eine Spielerfigur ins Wasser zu locken, sodass die anderen ihr helfen müssen. Der Nöck entkommt bald in die Tiefe, wo die Charaktere ihn nicht sehen können.",
            "Nachdem Pers Ida ertrunken aufgefunden wurde, ist Mattias Freja völlig am Boden zerstört und schluchzt unaufhörlich. Eine Spielerfigur kann sie mit einer gelungenen Probe auf INSPIRATION trösten. Dann vertraut sie den Spielercharakteren und tut alles, um ihnen zu helfen, besonders bei der Konfrontation."],
   hinwText:"Die Spielercharaktere können an der Fudalbucht viele Informationen gewinnen:",
   hinw:[
    {id:"b1", x:"Eine Figur, die den See beobachtet, bemerkt, dass es an der Fudalbucht sehr viele Seerosen gibt."},
    {id:"b2", x:"Eine gelungene Probe auf NACHFORSCHUNG enthüllt Fußspuren, die zum Wasser führen. Sie stammen von einem Menschen mit nackten Füßen, der mehr als einmal hin- und zurückgegangen ist. Nach der Fußgröße muss es eine Frau gewesen sein, doch eine genaue Identität lässt sich nicht feststellen. Lisbets Boel hat diese Spuren hinterlassen, als sie zum See hin- und zurückging."},
    {id:"b3", x:"Nachts können die Spielercharaktere mit einer Probe auf WACHSAMKEIT die Gestalt eines Fiedlers erkennen, der in kurzer Entfernung am Ufer entlangwandert. Das ist der Nöck in Menschengestalt. Er sagt nicht viel, wenn sie ihn ansprechen. Die Spielercharaktere können sein unmenschliches drittes Auge enthüllen, indem sie ihm den Hut entreißen, der es verbirgt, oder mit einer gelungenen Probe auf BEOBACHTUNG."},
    {id:"b4", q:"Handout 1C", x:"Haben die Spielercharaktere Jons Gustavs Liebesbrief noch nicht gefunden, können sie ihn mit einer gelungenen Probe auf NACHFORSCHUNG treibend im Wasser finden, unter einem Büschel Seerosen. Lisbets Boel hat versucht, ihn loszuwerden, indem sie ihn in den See warf. Der Brief ist als Handout 1C abgedruckt."},
    {id:"b5", x:"Der alte Wandteppich des Nöcks könnte ins Wasser geworfen worden sein; in diesem Fall können die Spielercharaktere ihn mit einer gelungenen Probe auf NACHFORSCHUNG finden. Pers Ida kann ihn auch bei sich haben, wenn Schritt 2 des Countdowns eingetreten ist. Mehr dazu im Kasten auf S. 18."},
    {id:"b6", x:"Ist Schritt 2 des Countdowns ausgelöst worden, kann Pers Idas lebloser Körper an der Fudalbucht gefunden werden. Spielercharaktere, die ausdrücklich angekündigt haben, am frühen Morgen nach Schritt 2 die Fudalbucht zu untersuchen, finden ihre Leiche; andernfalls holt Mattias Freja sie. Eine Spielerfigur, die nachts wach ist, kann mit einer gelungenen Probe auf WACHSAMKEIT Geräusche vom See hören, kommt aber nicht rechtzeitig dorthin, um Pers Ida vor dem Ertrinken zu retten."}
   ],
   kasten:[
    {t:"Pers Idas Leiche", x:"Wenn die Spielercharaktere Pers Idas Leiche finden, bietet sich ihnen ein tragischer Anblick. Lies den folgenden Text vor oder gib ihn sinngemäß wieder, um Stimmung zu erzeugen.", vor:"Mit dem Gesicht nach unten treibt zwischen den Seerosen der Körper einer jungen Frau. Ihre Arme sind ausgestreckt, und ihr großes weißes Nachthemd und das blonde Haar lassen sie fast wie ein makabres Gemälde eines Engels im Wasser wirken. Ihre blasse Haut hat dieselbe Farbe wie das Nachthemd angenommen. Als ihr den Körper umdreht, seht ihr, dass es Pers Ida ist. Ihre Augen sind geschlossen, und ihr Gesicht sähe fast friedlich aus, wäre es nicht ganz blau und aufgedunsen. Sie ist eiskalt. Dieses unschuldige Mädchen liegt nun tot vor euch. Wer würde etwas so Grausames tun, ihr junges Leben zu nehmen?", p:20}
   ]
  }
 ],

 kf: {
  p: 21,
  einleitung:["Lisbets Boel befürchtet, dass die Spielercharaktere ihr auf der Spur sind. Es ist Zeit für sie und den Nöck, ihren Plan auszuführen. Nach Einbruch der Dunkelheit trifft sie sich mit Jons Gustav an der Fudalbucht, wo sie andeutet, dass sie seine Liebe erwidert. Bald steigt der Nöck aus dem Wasser, und Jons Gustav begreift, dass er in eine Falle gelaufen ist. In seiner Verzweiflung versucht er, die Fiedel des Nöcks zu stehlen, und zur Strafe verflucht ihn der Nöck, bezaubernde Musik zu spielen, bis er keine Finger mehr hat. Ist Jons Gustav etwas zugestoßen, spielt der Nöck die Fiedel selbst.",
              "Die Musik erreicht Fudal, und die Erste, die sie hört, ist Swärds Jenny, die der Musik am Bach entlang folgt, um im See ertränkt zu werden. Die Spielercharaktere können das sehen, wenn sie anwesend und wach sind; andernfalls kommt eine panische Mattias Freja zu ihnen und bittet um Hilfe. Jeder, den die Melodie verzaubert, geht denselben Weg wie eine Spielerfigur, die in Schritt 1 des Countdowns verzaubert wurde.",
              "Die Zeit drängt, wenn sie Swärds Jenny vor dem Ertrinken retten wollen. Die Spielercharaktere können Musik von der Fudalbucht hören, wo der Nöck wartet. Mattias Freja macht sich auch Sorgen um Lisbets Boel, die in dieser Nacht nicht in ihrer Hütte war.",
              "Wenn die Spielercharaktere Lisbets Boel verletzen, fangen oder bedrohen, ruft der Nöck Jons Gustav herbei und zwingt ihn, Musik zu spielen, um Swärds Jenny dorthin zu locken. Lisbets Boel könnte zu fliehen versuchen, wenn die Konfrontation beginnt, oder auch vor Freude lachen, weil ihr Plan fast aufgeht. Die Konfrontation kann weitgehend wie beschrieben ablaufen, nur ohne ihre Beteiligung. Alternativ kann Lisbets Boel entkommen und als Bedrohung dienen, wenn die Spielercharaktere nach Fudal zurückkehren, etwa wenn sie versuchen, den Nöck dorthin zu locken, indem sie Mattias Freja oder ein anderes Mädchen als Gefangene nehmen und drohen, ihr die Kehle durchzuschneiden."],
  show: {t:"Showdown", x:["Wenn die Spielercharaktere an der Fudalbucht ankommen, sitzt der Nöck in seiner wahren Gestalt auf einem Felsen im Wasser und spielt Fiedel, um sein nächstes Opfer anzulocken. Swärds Jenny ist völlig verzaubert und vom Nöck gesteuert. Jons Gustav übernimmt das Spiel und bewegt sich nach dem Willen des Nöcks. In seinen Augen glitzern Tränen. Lisbets Boel steht am Strand und schreit um Hilfe, plant aber in Wahrheit, jeden zu ertränken, der sich nähert, angefangen bei Mattias Freja.",
   "Der Nöck hat absichtlich auf die Ankunft der Spielercharaktere gewartet, damit sie Zeugen seiner Macht werden. Sehen sie den Nöck zum ersten Mal in seiner wahren Gestalt, müssen die Spielercharaktere eine Furchtprobe gegen Furcht 1 ablegen.",
   "Der Nöck befiehlt Jons Gustav, Swärds Jenny innerhalb von W6 Runden zu ertränken. Will der Spielleiter den Nöck besonders grausam erscheinen lassen, kann er Jons Gustav auch sich selbst ertränken lassen, wenn die Lage schiefgeht. Währenddessen tut Lisbets Boel alles, damit der Plan gelingt, bringt persönlich weitere Menschen zum Ertränken und hält jeden auf, der den Nöck oder Jons Gustav angreift. Der Nöck setzt gegen die Spielercharaktere vor allem seinen Zauber MAGISCHES INSTRUMENT ein (funktioniert wie der Trollkunst-Zauber TANZ, siehe S. 120 im Grundregelwerk), um sie am Eingreifen zu hindern. Wird eine Spielerfigur Gebrochen, lockt der Nöck sie ebenfalls ins Wasser.",
   "Spielercharaktere, die ein Messer besitzen, das Fiedelsaiten durchtrennt hat (zum Beispiel die Saiten von Jons Gustavs Fiedel), können es in den Boden stecken und mit dem Nöck sprechen; das hindert ihn am Zaubern, solange das Messer im Boden steckt. Diese Information steht in dem unfertigen Brief, den Jons Gustav bei sich trug (siehe Handout 1E). Haben die Spielercharaktere den Zettel nicht gefunden, lässt Jons Gustav ihn während des Showdowns fallen, zum Beispiel wenn er getroffen wird oder ihn jemand stiehlt."]},
  bann: {t:"Den Bann brechen", x:["Jons Gustav ist die Person, deren Musik Swärds Jenny verzaubert hat, und sobald er aufhört zu spielen, ist sie (und jeder andere, der angelockt wurde) frei. Die Spielercharaktere können das erreichen, indem sie ihn mit einer gelungenen Probe auf NAHKAMPF gegen seine BEWEGLICHKEIT überwältigen. Bei Erfolg gelingt es ihnen, ihn festzuhalten, während eine andere Spielerfigur frei handeln kann (oder in der nächsten Runde, dann aber versucht Jons Gustav, sich loszureißen). Sie können entweder die Saiten der Fiedel durchschneiden (gelingt automatisch) oder sie ihm mit einer schwierigen Probe auf KRAFT aus den Händen reißen. Spielercharaktere ohne Messer können Jons Gustavs Messer mit einer gelungenen Probe auf HEIMLICHKEIT greifen und dann in derselben Runde die Saiten durchschneiden.",
   "Sobald Jons Gustav aufhört zu spielen, ist der Zauber aufgehoben. Die von seiner Musik Verzauberten sind nicht mehr in Gefahr zu ertrinken und eilen aus dem Wasser. Vielleicht sind sie auch bereit, den Spielercharakteren zu helfen, den Nöck aufzuhalten.",
   "Ist er vom Zauber befreit, empfindet Jons Gustav ungeheure Schuld über das Geschehene und opfert sich womöglich, um den Nöck notfalls abzulenken.",
   "Sie können auch versuchen, den Zauber zu brechen, der Lisbets Boel unter der Kontrolle des Nöcks hält. Mit einer schwierigen Probe auf INSPIRATION können sie zu ihr durchdringen und ihr klarmachen, dass der Nöck sie verzaubert hat. Die Hilfe von Mattias Freja gibt +1 auf ihren Wurf. Dann tut sie alles, um der Figur zu helfen, ihn aufzuhalten, und ruft alle nötigen Informationen zu. Gelingt es nicht, zu Lisbets Boel durchzudringen, versucht der Nöck womöglich, stattdessen sie zu ertränken."]},
  nock: {t:"Den Nöck bannen", x:["Um den Nöck zu bannen, müssen die Spielercharaktere seinen Zauber über Jons Gustav und Lisbets Boel brechen, entweder durch die im vorigen Abschnitt beschriebenen Proben oder indem sie den Nöck überzeugen, die Verzauberten freizugeben, indem sie ein Messer, das Fiedelsaiten durchtrennt hat, in den Boden stecken. Um ihn zu überzeugen, müssen sie ihm klarmachen, dass die Person, in die er sich verliebt hat, Lisbets Boel, in seinem Reich nicht überleben wird. Die Einsamkeit des Nöcks ist groß, doch seine Liebe zu Lisbets Boel ist noch größer, und er hebt die Verzauberung auf, wenn die Spielercharaktere ihn dazu bringen, zuzuhören.",
   "Ist der Zauber gebrochen, entweder durch den Nöck selbst oder dadurch, dass Jons Gustav und Lisbets Boel gerettet wurden, taucht der Nöck in den Siljan und verschwindet in der Tiefe, um nie wieder gesehen zu werden.",
   "Man kann den Nöck angreifen, zum Beispiel erschießen. Erleidet der Nöck 2 Schadenspunkte, verzaubert er die Person, die ihn angegriffen hat. Gegen alle Spielercharaktere setzt er hauptsächlich Tanz ein (siehe S. 120 im Grundregelwerk). Solange die Spielercharaktere verhext sind, kann einer der zum See gelockten Nichtspielercharaktere ertränkt werden.",
   "Der Nöck wird auch gebannt, wenn man ihn mit christlichen Symbolen oder Stahl umgibt, zum Beispiel wenn die Spielercharaktere einen Kreis um ihn bilden und Kruzifixe halten. In diesem Fall verwandelt sich der Nöck in eine Kröte, verschwindet im Wasser und verlässt den Siljan für immer.",
   "Spielercharaktere, die nach christlichen Symbolen oder Stahl suchen, um den Nöck zu bannen, finden beides im Hüttendorf mit einer gelungenen Probe auf NACHFORSCHUNG; jeder Erfolg bedeutet, dass sie ein christliches Symbol (etwa ein Kruzifix in einer Hütte) oder ein Stück Stahl (etwa unter den Werkzeugen) finden."]}
 },

 ns: {p: 23, t: "Nachspiel", x:["Gelingt es den Spielercharakteren, den Nöck zu bannen und Fudal vor dem Ertrinken zu bewahren, sind ihnen alle auf der Fäbodvall für immer dankbar. Haben Lisbets Boel und Jons Gustav überlebt, sind beide vom Zauber des Nöcks befreit und zeigen tiefe Reue über alles, was geschehen ist, obwohl sie keine Kontrolle darüber hatten. Am nächsten Tag feiern alle ihnen zu Ehren ein großes Fest und bieten ihnen reichlich Essen und Trinken an. Es wird getanzt, und die Luft ist erfüllt vom lieblichen Gesang der Almmägde – aber an diesem Tag spielt niemand Fiedel. Die Spielercharaktere reisen außerdem mit Geschenken der Mädchen von Fudal ab: Milch und Käse von den Kühen sowie ein geschnitztes Kuhhorn.",
   "Ist der Nöck zwar am Leben, aber aus dem Siljan verbannt, wird es viele Jahre dauern, bis jemand wieder seine Musik hört; doch schließlich findet er irgendwo weit entfernt neue Gewässer, wo er seine schwermütigen Weisen spielt, in dem Wissen, dass er für den Rest seiner Tage allein sein wird.",
   "Nun können die Spielercharaktere kaum mehr tun, als in ihr Hauptquartier in Upsala zurückzukehren, wo sie Erfahrungspunkte erhalten."]},

 /* Figuren: Werte am Buchseitenbild geprüft. a = Physis, Präzision, Logik, Empathie */
 figs: {
  jenny: {n:"Swärds Jenny", rolle:"Hofbesitzerin", zitat:"„Ich kümmere mich um meine Tiere ebenso wie um meine Kullor.“", p:8, img:"som/tod_swaerds_jenny",
   x:"Jenny ist eine Frau mittleren Alters aus einer Soldatenfamilie. Als einziges Kind erbte sie den Familienhof in Nusnäs und führt ihn mit Stolz. Im Sommer verbringt sie die meiste Zeit auf der Fäbodvall. Sie sorgt sich sehr um die bei ihr angestellten Mädchen und behandelt sie mit großem Respekt.<br><br>Man merkt, dass Swärds Jenny aus einer Soldatenfamilie stammt: Sie spricht unverblümt und direkt und stellt Forderungen an andere. Sie ist stets gerecht, und trotz ihres etwas strengen Auftretens hat sie ein goldenes Herz und beschützt die Menschen in ihrer Nähe sehr. Sie spricht mit Autorität und genießt den Respekt der Almmägde.<br><br>Ihr Äußeres spiegelt ihre Persönlichkeit: Sie trägt das braune Haar hochgesteckt und praktische Kleidung.",
   a:[4,2,2,2], f:[["Kraft",3],["Beobachtung",1],["Beweglichkeit",2],["Fernkampf",2]], z:[1,2], ausr:"Gewehr und Messer", hier:"Wiese · Hüttendorf"},
  boel: {n:"Lisbets Boel", rolle:"Almmagd · vom Nöck verzaubert", zitat:"„Ich lausche der süßen Musik des Lebens!“", p:14, img:"som/tod_lisbets_boel",
   x:"Lisbets Boel ist ein freundliches, aufgeschlossenes Mädchen in den Zwanzigern. Sie hat wallendes dunkelblondes Haar, das gut zu ihrer gebräunten Haut passt.<br><br>Ihre extrovertierte Art hat sie zu einer der beliebtesten Almmägde von Fudal gemacht. Bei jedem Fest oder Tanz steht sie meist im Mittelpunkt. Niemand weiß, dass sie plant, sie alle dem Nöck zu opfern.<br><br>Ihre engste Freundin ist Mattias Freja, die mit ihr die Hütte teilt, und Lisbets Boel weiß, dass sie ihr alles erzählen kann.<br><br>Die ganze Energie, die in ihr sprudelt, hält sie nachts oft wach. Dann geht sie meist zum Siljan hinunter und blickt über das Wasser. So traf sie den Nöck zum ersten Mal und wurde von seinen Weisen verführt. Nun will sie alles tun, um an seiner Seite zu sein, und ist bereit, alle anderen sterben zu lassen, um ihm zu gefallen. Sie begreift nicht, dass sie nur eine Marionette unter seinem Zauber ist.",
   a:[2,2,3,3], f:[["Beweglichkeit",2],["Manipulation",2],["Wachsamkeit",1]], z:[2,1], ausr:"", hier:"Wiese · Hüttendorf · Fudalbucht"},
  ida: {n:"Pers Ida", rolle:"Almmagd · schüchtern", zitat:"„Die Natur verdient Ehrfurcht.“", p:14, img:"som/tod_pers_ida",
   x:"Pers Ida ist Anfang zwanzig und eines der jüngsten Mädchen in Fudal. Sie ist eine Träumerin mit fast weißblondem Haar, milchweißer Haut und großen blauen Augen – wie aus einem Märchen.<br><br>Pers Ida hat tiefe Liebe und Achtung für die Natur. Sie kümmert sich gut um die Tiere in Fudal und singt ihnen oft mit ihrer seidenweichen Stimme vor. Im Umgang mit Menschen ist sie leider nicht so gut, denn sie ist oft still und sieht lieber anderen beim Gesellschaftsleben zu, statt selbst mitzumachen.<br><br>Sie hat auch einige Geschichten über verschiedene Vaesen gehört und ist bereit, ihr Wissen mit den Spielercharakteren zu teilen.<br><br>Sie begehrt Jons Gustav, würde es aber nie zugeben. Doch Lisbets Boel hat das erkannt und könnte es sich im Notfall zunutze machen.",
   a:[2,2,4,1], f:[["Beweglichkeit",1],["Heilkunde",2],["Gelehrsamkeit",2],["Wachsamkeit",2]], z:[1,1], ausr:"Kuhhorn", hier:"Hüttendorf · Wiese"},
  gustav: {n:"Jons Gustav", rolle:"Fiedler", zitat:"„Ich werde der beste Fiedler sein, den Dalarna je gesehen hat, koste es, was es wolle!“", p:15, img:"som/tod_jons_gustav",
   x:"Jons Gustav ist ein kleiner Mann in den Dreißigern mit lockigem rotem Haar und einem kleinen Bart. Er hat eine sehr kalte Persönlichkeit und zeigt kaum Gefühle.<br><br>Er stammt aus einer kinderreichen Bauernfamilie und erbte nur ein kleines Stück Land, das seine Geschwister ihm dann abkauften. In der Hoffnung, sich seinen Lebensunterhalt zu verdienen, begann er als Fiedler zu arbeiten. Obwohl er technisch begabt ist, war sein Spiel ziemlich einfach und gefühllos.<br><br>Er ist besessen davon, ein meisterhafter Fiedler zu werden, und suchte deshalb Unterricht beim Nöck. Aber er ist ein Feigling und steckt nun in großen Schwierigkeiten, da die Zeit gekommen ist, seinen Teil des Handels zu erfüllen.<br><br>Er kennt den Trollkunst-Zauber TANZ (BEOBACHTUNG) und kann ihn im Kampf einsetzen. Siehe S. 120 im Grundregelwerk.",
   a:[4,3,2,1], f:[["Kraft",2],["Wachsamkeit",1],["Nahkampf",1],["Manipulation",2],["Heimlichkeit",2],["Magie",2]], z:[1,2], ausr:"Fiedel und Messer", hier:"Wiese · Wald"},
  freja: {n:"Mattias Freja", rolle:"Almmagd · Anführerin der Mädchen", zitat:"„Es ist wichtig, dass wir alle zusammenarbeiten.“", p:15, img:"som/tod_mattias_freja",
   x:"Mattias Freja ist Ende zwanzig. Sie hat dunkelbraunes Haar, zum Pferdeschwanz gebunden, im scharfen Kontrast zu ihrer hellen Haut. Sie ist ein äußerst einfühlsamer und diplomatischer Mensch, der glaubt, dass Harmonie der Schlüssel zu einem effizienten Arbeitsumfeld ist. Sie leitet meist mehrere Mädchen bei der Arbeit an, wenn die Bauern nicht da sind.<br><br>Zugleich hat ihre starke Empathie sie sensibel gemacht, und sie reagiert leicht emotional, besonders auf Widrigkeiten.<br><br>Sie steht Lisbets Boel sehr nahe und würde für sie sterben, wenn es darauf ankäme. Die Wahrheit ist, dass Freja in Boel verliebt ist, aber weiß, dass sie es nie zugeben könnte. Aber träumen darf man…<br><br>Sie hatte früher einen schwarzen Kater, Nisse, doch er verschwand vor einem Monat. Sie vermisst ihn immer noch.",
   a:[2,2,2,4], f:[["Kraft",1],["Inspiration",2],["Wachsamkeit",2],["Beobachtung",1]], z:[2,1], ausr:"", hier:"Wiese · Hüttendorf · Fudalbucht"},
  maegde: {n:"Almmägde", rolle:"Gruppe", zitat:"„Hast du diesen Käse probiert? Den habe ich selbst gemacht!“", p:16, img:"",
   x:"Die Almmägde sind relativ jung, die meisten in den Zwanzigern, einige Anfang dreißig. Sie werden von den Bauern dafür bezahlt, deren Vieh in Fudal zu hüten. Angestellte Mädchen sind fast ausschließlich unverheiratete Kullor – die verheirateten sind meist zu Hause und kümmern sich um den Hof, verbringen aber gelegentlich einige Zeit bei ihren Tieren auf der Fäbodvall. Die meisten Almmägde sind freundlich und fröhlich, und alle feiern und tanzen gern.",
   a:[2,2,3,3], f:[["Kraft",1],["Heimlichkeit",1],["Wachsamkeit",1]], z:[2,1], ausr:"Kuhhorn und Werkzeuge, etwa ein Messer oder eine Axt", hier:"Hüttendorf"}
 },
 nock: {n:"Der Nöck", p:22, x:"Werte im Grundregelwerk S. 144. Zauber im Mysterium: MAGISCHES INSTRUMENT (wirkt wie der Trollkunst-Zauber TANZ, Grundregelwerk S. 120). Furchtprobe gegen Furcht 1 beim ersten Anblick der wahren Gestalt. Empfindlich gegen christliche Symbole und Stahl."},

 /* Handouts: Papier-Bild (img/som/ho_…), Text, Format */
 ho: [
  {id:"1a", t:"Handout 1A", u:"Brief von Swärds Jenny", paper:"ho_1a", form:"brief", klein:1},
  {id:"1b", t:"Handout 1B", u:"Der Zettel auf dem Bett", paper:"ho_1b", form:"zettel", x:"Neugierige Leute wie ihr täten gut daran, zu gehen. Lasst uns das selbst regeln."},
  {id:"1c", t:"Handout 1C", u:"Jons Gustavs Liebesbrief", paper:"ho_1c", form:"brief", x:"Meine liebste Boel,<br><br>dein Haar ist so schön wie frisch gesponnene Saiten, und deine Stimme klingt wie die erlesenste Musik. Du bist die schönste Frau, die ich kenne. Du lässt mein Herz in meiner Brust schlagen wie eine Trommel. Es schlägt für dich und für dich allein.<br><br>Aber ich weiß, dass dein Herz für einen anderen schlägt. Ich weiß, dass auch er ein Fiedler ist.<br><br>Doch ich verspreche dir, meine Liebe, dass bald die Zeit kommen wird, in der ich der größte Fiedler sein werde, den Fudal je gesehen hat, und dann wirst du mir nicht mehr widerstehen können. Zusammen werden wir sehr süße Musik machen.<br><br>Dein liebender Jons Gustav"},
  {id:"1d", t:"Handout 1D", u:"Auszug aus Pers Idas Tagebuch", paper:"ho_1d", form:"tagebuch", x:"Seit die Kuh verschwunden ist, versuche ich, nachts Wache zu halten. Gestern habe ich etwas an der Bucht gesehen. Ich glaubte, jemanden im Wasser zu sehen. Aber am meisten überraschte mich eine Frau, die mit der seltsamen Gestalt sprach. Ich konnte nicht sehen, wer es war, bevor sie weglief. Sie muss mich gesehen haben. Ich muss herausfinden, wer das war. Vielleicht ist das der Schlüssel zu allem, was vor sich geht?"},
  {id:"1e", t:"Handout 1E", u:"Jons Gustavs unfertiger Brief", paper:"ho_1e", form:"brief", x:"Meine Geliebte,<br><br>lauf mit mir fort und sei mein. Mit seiner Fiedel werde ich frei sein von dem Pakt, der mich hier hält, und du wirst die süßeste Musik hören. Aber wenn er dir nachkommt, nimm dieses Messer, denn es hat die Saiten von Fiedeln durchtrennt. Steck es in den Boden, und es wird dich schützen.<br><br>Es tut mir leid um die arme Katze und das Schicksal, das sie erlitt. Ich hoffe, du wirst mir verzei…"}
 ]
};
